START TRANSACTION;
ALTER TABLE "Survey" ADD "ProductId" integer;

ALTER TABLE "QuestionOption" ADD "PreferenceId" integer;

ALTER TABLE "Feedback" ADD "OrderItemId" integer;

ALTER TABLE "CustomerPreference" ADD "CreatedAt" timestamp with time zone NOT NULL DEFAULT TIMESTAMPTZ '-infinity';

ALTER TABLE "CustomerPreference" ADD "Source" character varying(32) NOT NULL DEFAULT 'Declared';

CREATE TABLE "Order" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" character varying(20) NOT NULL,
    "CustomerId" integer NOT NULL,
    "Channel" character varying(32) NOT NULL,
    "Status" character varying(32) NOT NULL,
    "TotalAmount" numeric(12,0) NOT NULL,
    "OrderedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Order" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Order_CustomerProfile_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "CustomerProfile" ("AccountId") ON DELETE RESTRICT
);

CREATE TABLE "RecommendationPlan" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(120) NOT NULL,
    "Goal" character varying(1000),
    "Segment" jsonb NOT NULL,
    "Status" character varying(32) NOT NULL,
    "StartAt" timestamp with time zone NOT NULL,
    "EndAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_RecommendationPlan" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_RecommendationPlan_Dates" CHECK ("EndAt" > "StartAt"),
    CONSTRAINT "FK_RecommendationPlan_StaffProfile_CreatedBy" FOREIGN KEY ("CreatedBy") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT
);

CREATE TABLE "OrderItem" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" integer NOT NULL,
    "ProductVariantId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "UnitPrice" numeric(12,0) NOT NULL,
    CONSTRAINT "PK_OrderItem" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_OrderItem_Quantity" CHECK ("Quantity" > 0),
    CONSTRAINT "FK_OrderItem_Order_OrderId" FOREIGN KEY ("OrderId") REFERENCES "Order" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_OrderItem_ProductVariant_ProductVariantId" FOREIGN KEY ("ProductVariantId") REFERENCES "ProductVariant" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Recommendation" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CustomerId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "Score" numeric(5,4) NOT NULL,
    "Breakdown" jsonb NOT NULL,
    "Reasons" jsonb NOT NULL,
    "PlanId" integer,
    "Status" character varying(32) NOT NULL,
    "GeneratedAt" timestamp with time zone NOT NULL,
    "InteractedAt" timestamp with time zone,
    CONSTRAINT "PK_Recommendation" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Recommendation_Score" CHECK ("Score" BETWEEN 0 AND 1),
    CONSTRAINT "FK_Recommendation_CustomerProfile_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "CustomerProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_Recommendation_Product_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Product" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Recommendation_RecommendationPlan_PlanId" FOREIGN KEY ("PlanId") REFERENCES "RecommendationPlan" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "RecommendationPlanProduct" (
    "PlanId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "SortOrder" integer NOT NULL,
    CONSTRAINT "PK_RecommendationPlanProduct" PRIMARY KEY ("PlanId", "ProductId"),
    CONSTRAINT "FK_RecommendationPlanProduct_Product_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Product" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_RecommendationPlanProduct_RecommendationPlan_PlanId" FOREIGN KEY ("PlanId") REFERENCES "RecommendationPlan" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_Survey_ProductId" ON "Survey" ("ProductId");

CREATE INDEX "IX_QuestionOption_PreferenceId" ON "QuestionOption" ("PreferenceId");

CREATE UNIQUE INDEX "IX_Feedback_OrderItemId" ON "Feedback" ("OrderItemId");

CREATE UNIQUE INDEX "IX_Order_Code" ON "Order" ("Code");

CREATE INDEX "IX_Order_CustomerId_OrderedAt" ON "Order" ("CustomerId", "OrderedAt" DESC);

CREATE INDEX "IX_OrderItem_OrderId" ON "OrderItem" ("OrderId");

CREATE INDEX "IX_OrderItem_ProductVariantId" ON "OrderItem" ("ProductVariantId");

CREATE UNIQUE INDEX "IX_Recommendation_CustomerId_ProductId" ON "Recommendation" ("CustomerId", "ProductId") WHERE "Status" = 'Active';

CREATE INDEX "IX_Recommendation_CustomerId_Status" ON "Recommendation" ("CustomerId", "Status");

CREATE INDEX "IX_Recommendation_PlanId" ON "Recommendation" ("PlanId");

CREATE INDEX "IX_Recommendation_ProductId" ON "Recommendation" ("ProductId");

CREATE INDEX "IX_RecommendationPlan_CreatedBy" ON "RecommendationPlan" ("CreatedBy");

CREATE INDEX "IX_RecommendationPlanProduct_ProductId" ON "RecommendationPlanProduct" ("ProductId");

ALTER TABLE "Feedback" ADD CONSTRAINT "FK_Feedback_OrderItem_OrderItemId" FOREIGN KEY ("OrderItemId") REFERENCES "OrderItem" ("Id") ON DELETE RESTRICT;

ALTER TABLE "QuestionOption" ADD CONSTRAINT "FK_QuestionOption_Preference_PreferenceId" FOREIGN KEY ("PreferenceId") REFERENCES "Preference" ("Id") ON DELETE RESTRICT;

ALTER TABLE "Survey" ADD CONSTRAINT "FK_Survey_Product_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Product" ("Id") ON DELETE RESTRICT;

